-- ============================================================================ -- 012_phase2_pit_research_schema.sql -- WEALTHOS / ITAS v6.3: PHASE 2 POINT-IN-TIME RESEARCH SCHEMA EXTENSIONS -- ============================================================================
-- 1. Historical Investable Universe (Survivorship Bias Elimination) CREATE TABLE IF NOT EXISTS historical_investable_universe ( id INTEGER PRIMARY KEY AUTOINCREMENT, symbol TEXT NOT NULL, universe TEXT NOT NULL, effective_from TEXT NOT NULL, -- YYYY-MM-DD effective_to TEXT, -- YYYY-MM-DD or NULL if currently active eligibility_status TEXT NOT NULL CHECK(eligibility_status IN ('ACTIVE', 'SUSPENDED', 'DELISTED')), transition_reason TEXT NOT NULL CHECK(transition_reason IN ( 'INITIAL_INCLUSION', 'REBALANCE_ADDITION', 'REBALANCE_REMOVAL', 'DELISTING', 'CORPORATE_MERGER', 'SYMBOL_CHANGE' )), source TEXT NOT NULL, source_record_id TEXT NOT NULL, available_at TEXT NOT NULL, -- ISO-8601 with timezone offset created_at DATETIME DEFAULT CURRENT_TIMESTAMP, UNIQUE(symbol, universe, effective_from) );
CREATE INDEX IF NOT EXISTS idx_hiu_sym_dates ON historical_investable_universe(symbol, effective_from, effective_to); CREATE INDEX IF NOT EXISTS idx_hiu_universe ON historical_investable_universe(universe);
-- 2. Authoritative Trading Calendar (Market Sessions & Operational Schedule) CREATE TABLE IF NOT EXISTS authoritative_trading_calendar ( date TEXT PRIMARY KEY, -- YYYY-MM-DD market_open TEXT NOT NULL, -- HH:MM:SS+OFFSET e.g. "09:15:00+05:30" market_close TEXT NOT NULL, -- HH:MM:SS+OFFSET e.g. "15:30:00+05:30" tradable INTEGER NOT NULL CHECK(tradable IN (0, 1)), session_type TEXT NOT NULL CHECK(session_type IN ( 'REGULAR', 'MUHURAT', 'SPECIAL', 'CLOSED', 'WEEKEND', 'HOLIDAY' )), session_identifier TEXT NOT NULL, holiday_reason TEXT, source TEXT NOT NULL, available_at TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP );
CREATE INDEX IF NOT EXISTS idx_atc_tradable_date ON authoritative_trading_calendar(tradable, date);
-- 3. Reconciled Corporate Actions (Splits, Bonuses, Dividends with Provenance) CREATE TABLE IF NOT EXISTS corporate_actions_reconciled ( id INTEGER PRIMARY KEY AUTOINCREMENT, symbol TEXT NOT NULL, action_type TEXT NOT NULL CHECK(action_type IN ( 'SPLIT', 'BONUS', 'DIVIDEND', 'RIGHTS', 'MERGER', 'SYMBOL_CHANGE' )), ex_date TEXT NOT NULL, -- YYYY-MM-DD record_date TEXT, -- YYYY-MM-DD ratio_numerator REAL, ratio_denominator REAL, amount REAL, adjustment_convention TEXT NOT NULL CHECK(adjustment_convention IN ( 'RAW', 'ADJUSTED', 'RECONSTRUCTED' )), economic_timestamp TEXT NOT NULL, available_at TEXT NOT NULL, source TEXT NOT NULL, source_record_id TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, UNIQUE(symbol, action_type, ex_date) );
CREATE INDEX IF NOT EXISTS idx_car_sym_exdate ON corporate_actions_reconciled(symbol, ex_date);
-- 4. Point-In-Time Disclosure Registry (Financial Statements & Shareholding Patterns) CREATE TABLE IF NOT EXISTS pit_disclosure_registry ( id INTEGER PRIMARY KEY AUTOINCREMENT, symbol TEXT NOT NULL, disclosure_kind TEXT NOT NULL CHECK(disclosure_kind IN ( 'FINANCIAL_STATEMENT', 'SHAREHOLDING_PATTERN' )), period_label TEXT NOT NULL, period_end_date TEXT NOT NULL, -- YYYY-MM-DD publication_timestamp TEXT NOT NULL,-- ISO-8601 available_at TEXT NOT NULL, -- ISO-8601, MUST BE > period_end_date source TEXT NOT NULL, source_record_id TEXT NOT NULL, payload_json TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, UNIQUE(symbol, disclosure_kind, period_label) );
CREATE INDEX IF NOT EXISTS idx_pdr_sym_avail ON pit_disclosure_registry(symbol, available_at);

wealthos_system_blueprint.production_engine:
/**
 * PureTechnicalStrategiesEngine.ts
 *
 * Standalone Independent Technical Analysis Engine for NRI WealthOS.
 * Strictly implements three independent technical momentum strategies WITHOUT
 * mixing any fundamentals, sentiment, valuation, market cap, or external dampers.
 *
 * Strategy 1: VPA Alignment & Base Compaction Breakout
 * Strategy 2: Institutional Inflow + FVG & Consequent Encroachment (CE) Pullback
 * Strategy 3: Higher High & Higher Low Sequential Compaction with Smart Money Flag
 */

import { SMA, EMA, RSI, ATR, BollingerBands } from 'technicalindicators';
import { fetchTickerData } from '../yahooFinance.js';
import { getDB, dbAll, dbGet, dbRun } from '../database.js';
import { StrategyParameterConfig, getDefaultsForStrategy } from './StrategyParameterConfig.js';

export interface Candle {
  date: string;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
  turnover?: number;
}

export interface RuleCheck {
  id: string;
  name: string;
  passed: boolean;
  actualValue: string | number;
  benchmarkRule: string;
  explanation: string;
}

// ─────────────────────────────────────────────────────────────────────────────
// STRATEGY 1 INTERFACES
// ─────────────────────────────────────────────────────────────────────────────

export interface StrategyEvaluationOptions {
  filterPreceding52wLow?: boolean;
  config?: StrategyParameterConfig;
}

export interface Strategy1Result {
  qualified: boolean;
  symbol: string;
  companyName: string;
  cmp: number;
  p0: number | null;
  peakHigh: number | null;
  impulseDurationBars: number | null;
  impulseGainPct: number | null;
  baseDurationBars: number | null;
  retracementFloor: number | null;
  lowestBaseClose: number | null;
  atrRatio: number | null;
  volumeDryingRatio: number | null;
  vpaAsymmetryRatio: number | null;
  isNr4: boolean;
  isNr7: boolean;
  ema9: number | null;
  ema21: number | null;
  ema9OverEma21: boolean;
  rsi14: number | null;
  stopLoss: number | null;
  target1: number | null;
  target2: number | null;
  riskRewardRatio: number | null;
  preceding52WeekLow: number | null;
  p0DistancePctFrom52wLow: number | null;
  isAtPreceding52WeekLow: boolean;
  signalStatus?: 'ACTIVE' | 'PASSED_OPPORTUNITY' | 'INVALIDATED' | 'MONITORING';
  signalAge?: number;
  ruleChecks: RuleCheck[];
}

// ─────────────────────────────────────────────────────────────────────────────
// STRATEGY 2 INTERFACES
// ─────────────────────────────────────────────────────────────────────────────

export interface FairValueGapInfo {
  index: number;
  date: string;
  topPrice: number;       // Candle i+1 low
  bottomPrice: number;    // Candle i-1 high
  ceLevel: number;        // Consequent Encroachment (50% midpoint)
  sizePct: number;
  isMitigated: boolean;
  mitigationPct: number;
}

export interface Strategy2Result {
  qualified: boolean;
  symbol: string;
  companyName: string;
  cmp: number;
  p0: number | null;
  p0Date?: string;
  impulseGainPct: number | null;
  cumulativeTurnoverCr: number | null;
  institutionalInflowDate: string | null;
  institutionalDayTurnoverCr: number | null;
  institutionalVolumeRatio: number | null;
  pullbackDurationBars: number | null;
  pullbackDropPct: number | null;
  pullbackVolumeDrying: boolean;
  priceRangeCompacted: boolean;
  priceContractionAtEntry: boolean;
  vpaAlignmentAtEntry: boolean;
  entryRangeContractionRatio: number | null;
  entryVolumeDryingRatio: number | null;
  activeFvg: FairValueGapInfo | null;
  entryZone: {
    recommendedEntryPrice: number; // CE Level
    fvgTop: number;
    fvgBottom: number;
    ceLevel: number;
  } | null;
  invalidationStopLoss: number | null;
  target1: number | null;
  target2: number | null;
  riskRewardRatio: number | null;
  preceding52WeekLow: number | null;
