export class TradingCalendarService {
  private static instance: TradingCalendarService;
  private dbSessionMap = new Map<string, MarketSession>();

  public static getInstance(): TradingCalendarService {
    if (!TradingCalendarService.instance) {
      TradingCalendarService.instance = new TradingCalendarService();
    }
    return TradingCalendarService.instance;
  }

  /**
   * Load authoritative sessions directly from database or fixture
   */
  public loadFromSessions(sessions: MarketSession[]): void {
    for (const s of sessions) {
      this.dbSessionMap.set(s.date, s);
    }
  }

  /**
   * Determine whether a given YYYY-MM-DD date is an active trading session.
   */
  public isTradingDay(dateStr: string): boolean {
    const session = this.getSessionInfo(dateStr);
    return session.isTradingDay;
  }

  /**
   * Full session details for a given date.
   */
  public getSessionInfo(dateStr: string): MarketSession {
    if (this.dbSessionMap.has(dateStr)) {
      return this.dbSessionMap.get(dateStr)!;
    }

    const d = new Date(`${dateStr}T00:00:00Z`);
    const dayOfWeek = d.getUTCDay(); // 0 = Sunday, 6 = Saturday

    const holiday = NSE_CALENDAR_MAP[dateStr];

    if (holiday) {
      if (holiday.type === 'MUHURAT') {
        return {
          date: dateStr,
          isTradingDay: true,
          sessionType: 'MUHURAT',
          holidayName: holiday.name,
          openTimeIST: '18:15',
          closeTimeIST: '19:15'
        };
      }
      return {
        date: dateStr,
        isTradingDay: false,
        sessionType: 'CLOSED',
        holidayName: holiday.name,
        openTimeIST: '00:00',
        closeTimeIST: '00:00'
      };
    }

    // Standard Weekend check
    if (dayOfWeek === 0 || dayOfWeek === 6) {
      return {
        date: dateStr,
        isTradingDay: false,
        sessionType: 'CLOSED',
        holidayName: dayOfWeek === 0 ? 'Sunday' : 'Saturday',
        openTimeIST: '00:00',
        closeTimeIST: '00:00'
      };
    }

    // Regular trading day
    return {
      date: dateStr,
      isTradingDay: true,
      sessionType: 'REGULAR',
      openTimeIST: '09:15',
      closeTimeIST: '15:30'
    };
  }

  /**
   * Returns the next valid trading day strictly after dateStr.
   * NEVER uses date + 1.
   */
  public getNextTradingDay(dateStr: string): string {
    let curr = new Date(`${dateStr}T00:00:00Z`);
    while (true) {
      curr.setUTCDate(curr.getUTCDate() + 1);
      const nextStr = curr.toISOString().split('T')[0];
      if (this.isTradingDay(nextStr)) {
        return nextStr;
      }
    }
  }

  /**
   * Returns the previous valid trading day strictly before dateStr.
   */
  public getPrevTradingDay(dateStr: string): string {
    let curr = new Date(`${dateStr}T00:00:00Z`);
    while (true) {
      curr.setUTCDate(curr.getUTCDate() - 1);
      const prevStr = curr.toISOString().split('T')[0];
      if (this.isTradingDay(prevStr)) {
        return prevStr;
      }
    }
  }

  /**
   * Returns list of all active trading days in range [startDate, endDate] inclusive.
   */
  public getTradingDaysBetween(startDate: string, endDate: string): string[] {
    const res: string[] = [];
    let curr = new Date(`${startDate}T00:00:00Z`);
    const end = new Date(`${endDate}T00:00:00Z`);

    while (curr <= end) {
      const dStr = curr.toISOString().split('T')[0];
      if (this.isTradingDay(dStr)) {
        res.push(dStr);
      }
      curr.setUTCDate(curr.getUTCDate() + 1);
    }
    return res;
  }
}

export type Direction = "LONG" | "SHORT" | "EXIT" | "HEDGE";
export type ExperimentArm = "A_RAW" | "B_V62_OVERLAY" | "C_CAPITAL_PROTECTION" | "C_CHALLENGERS" | "D_RISK_ORACLE" | "D_UNEXPOSED";
export type AblationLayer =
  | "RAW" | "SIGNAL_QUALITY" | "RISK_SIZING" | "GAP_RISK"
  | "CAPITAL_PROTECTION" | "EXIT_FRAMEWORK" | "ALL";

export interface ResearchBar {
  symbol: string;
  timestamp: string;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
  deliveryVolume: number;
  tradable: boolean;
  upperCircuit?: number;
  lowerCircuit?: number;
  availableAt: string;

  // Compatibility aliases
  date?: string;
  turnover?: number;
  deliveryQty?: number;
}

export interface SignalProvenance {
  dataMode: "REAL_HISTORICAL";
  decisionTimestamp: string;
  availableAt: string;
  sourceTables: string[];
  sourceRecordIds: string[];
  parameterHash: string;
  productionBaselineHash: string;
}

export interface ResearchSignal {
  signalId: string;
  strategyId: string;
  symbol: string;
  timestamp: string;
  availableAt?: string;
  direction: Direction;
  entry: number;
  stop: number;
  target?: number;
  quantityHint?: number;
  qualityScore?: number;
  reasons: string[];
  rawPayload?: Record<string, unknown>;
  provenance?: SignalProvenance;
}

export interface ExecutionConfig {
  initialCapital: number;
  brokeragePerLeg: number;
  sttRate: number;
  stampDutyBuyRate: number;
  exchangeTxnRate: number;
  gstRate: number;
  slippageBps: number;
  impactBps: number;
  maxParticipationPct: number;
  allowShortCash: boolean;

  // Simulation & Integrity Control Flags
  intrabarPolicy?: "CONSERVATIVE_STOP_FIRST" | "AGGRESSIVE_TARGET_FIRST";
  enforcePitTimestamps?: boolean;
  calendar?: any;
  enforceCalendarSessions?: boolean;
}

export function getDefaultExecutionConfig(overrides?: Partial<ExecutionConfig>): ExecutionConfig {
  return {
    initialCapital: 10_000_000,
    brokeragePerLeg: 20,
    sttRate: 0.001,
    stampDutyBuyRate: 0.00015,
    exchangeTxnRate: 0.0000345,
    gstRate: 0.18,
    slippageBps: 10,
    impactBps: 5,
    maxParticipationPct: 0.015,
    allowShortCash: false,
    intrabarPolicy: "CONSERVATIVE_STOP_FIRST",
    enforcePitTimestamps: true,
    ...overrides
  };
}

export interface Fill {
  timestamp: string;
  symbol: string;
  side: "BUY" | "SELL";
  quantity: number;
  requestedPrice: number;
  fillPrice: number;
