""" WealthOS In-Memory / SQLite Database Populator & Replay Driver Run this in Google AI Studio Code Execution to initialize an authentic in-memory or on-disk SQLite database and execute S1-S11 strategies. """ import sqlite3 import json import pandas as pd from datetime import datetime
class WealthOSDatabaseManager: def __init__(self, db_path=':memory:'): self.conn = sqlite3.connect(db_path) self.conn.row_factory = sqlite3.Row self.cursor = self.conn.cursor()
def init_schema(self, ddl_statements): for stmt in ddl_statements.split(';'): if stmt.strip(): self.cursor.execute(stmt) self.conn.commit()
def query(self, sql, params=()): self.cursor.execute(sql, params) return [dict(r) for r in self.cursor.fetchall()]
def insert_bars(self, bars): self.cursor.executemany(""" INSERT OR REPLACE INTO DailyOHLCV (symbol, date, open, high, low, close, volume, turnover, delivery_percentage) VALUES (:symbol, :date, :open, :high, :low, :close, :volume, :turnover, :delivery_percentage) """, bars) self.conn.commit()
